7. /// Sum of elements in `s` from index `from` (inclusive) to the end.
8. pub open spec fn seq_sum_from(s: Seq<int>, from: int) -> int
9.     decreases (if from < s.len() { s.len() - from } else { 0 }),
10. {
11.     if from >= s.len() {
12.         0
13.     } else {
14.         s[from] + seq_sum_from(s, from + 1)
15.     }
16. }
17. 
18. //==================================================================================================
19. // SparseBitmapView - Abstract Specification Model
20. //==================================================================================================
21. 
22. /// Abstract view of a SparseBitmap.
23. ///
24. /// Two fields capture the full caller-observable state:
25. /// - `chunks`: the fixed shape — which global index ranges are covered.
26. /// - `set_bits`: the mutable state — which covered indices have their bit set.
27. #[verifier::ext_equal]
28. pub struct SparseBitmapView {
29.     /// Sorted, non-overlapping chunk descriptors.
30.     /// Each element is (offset, num_bits) describing the half-open range
31.     /// [offset, offset + num_bits).
32.     pub chunks: Seq<(int, int)>,
33. 
34.     /// Set of global indices where bits are set.
35.     /// Always a subset of covered_indices().
36.     pub set_bits: Set<int>,
37. }
38. 
39. impl SparseBitmapView {
40.     /// Well-formedness invariant for the abstract view.
41.     pub open spec fn wf(&self) -> bool {
42.         // At least one chunk
43.         &&& self.chunks.len() > 0
44. 
45.         // All chunk offsets are non-negative
46.         &&& forall|i: int| #![auto] 0 <= i < self.chunks.len()
47.             ==> self.chunks[i].0 >= 0
48. 
49.         // All chunk sizes are positive
50.         &&& forall|i: int| #![auto] 0 <= i < self.chunks.len()
51.             ==> self.chunks[i].1 > 0
52. 
53.         // Chunk ranges do not overflow usize (representability)
54.         &&& forall|i: int| #![auto] 0 <= i < self.chunks.len()
55.             ==> self.chunks[i].0 + self.chunks[i].1 <= usize::MAX as int
56. 
57.         // Chunks are sorted and non-overlapping (touching permitted)
58.         &&& forall|i: int, j: int| #![auto] 0 <= i < j < self.chunks.len()
59.             ==> self.chunks[i].0 + self.chunks[i].1 <= self.chunks[j].0
60. 
61.         // set_bits only contains covered indices
62.         &&& forall|idx: int| #![auto] self.set_bits.contains(idx)
63.             ==> self.is_covered(idx)
64. 
65.         // set_bits is finite (required for len()/cardinality)
66.         &&& self.set_bits.finite()
67.     }
68. 
69.     /// Whether a global index is covered by some chunk.
70.     pub open spec fn is_covered(&self, index: int) -> bool {
71.         exists|i: int|
72.             #![trigger self.chunks[i]]
73.             0 <= i < self.chunks.len()
74.             && self.chunks[i].0 <= index
75.             && index < self.chunks[i].0 + self.chunks[i].1
76.     }
77. 
78.     /// The set of all globally covered indices.
79.     pub open spec fn covered_set(&self) -> Set<int> {
80.         Set::new(|idx: int| self.is_covered(idx))
81.     }
82. 
83.     /// Total number of bits across all chunks.
84.     pub open spec fn capacity(&self) -> int {
85.         self.capacity_from(0)
86.     }
87. 
88.     /// Capacity starting from chunk index `from` (recursive helper).
89.     pub open spec fn capacity_from(&self, from: int) -> int
90.         decreases self.chunks.len() - from
91.     {
92.         if from >= self.chunks.len() {
93.             0
94.         } else {
95.             self.chunks[from].1 + self.capacity_from(from + 1)
96.         }
97.     }
98. 
99.     /// Number of chunks.
100.     pub open spec fn chunk_count(&self) -> int {
101.         self.chunks.len() as int
102.     }
103. 
104.     /// Whether a specific bit is set.
105.     pub open spec fn is_bit_set(&self, index: int) -> bool {
106.         self.set_bits.contains(index)
107.     }
108. 
109.     /// Whether two adjacent chunks touch (chunk i's end == chunk j's start).
110.     pub open spec fn chunks_touch(&self, i: int, j: int) -> bool {
111.         &&& 0 <= i < self.chunks.len()
112.         &&& 0 <= j < self.chunks.len()
113.         &&& self.chunks[i].0 + self.chunks[i].1 == self.chunks[j].0
114.     }
115. 
116.     /// Whether the range [start, start + count) is entirely covered and free.
117.     pub open spec fn has_contiguous_free_range(&self, start: int, count: int) -> bool {
118.         &&& count > 0
119.         &&& forall|k: int| start <= k < start + count ==> self.is_covered(k)
120.         &&& forall|k: int| start <= k < start + count ==> !self.set_bits.contains(k)
121.     }
122. 
123.     /// Whether there exists some contiguous free range of the given size.
124.     pub open spec fn exists_contiguous_free_range(&self, count: int) -> bool {
125.         exists|start: int|
126.             #![trigger self.has_contiguous_free_range(start, count)]
127.             self.has_contiguous_free_range(start, count)
128.     }
129. 
130.     /// Whether chunk `ci` contains a single-chunk contiguous free range of `count` bits.
131.     /// The range [start, start+count) fits entirely within chunk ci.
132.     pub open spec fn has_single_chunk_free_range(&self, ci: int, count: int) -> bool {
133.         &&& 0 <= ci < self.chunks.len()
134.         &&& count > 0
135.         &&& exists|start: int| {
136.             &&& self.chunks[ci].0 <= start
137.             &&& start + count <= self.chunks[ci].0 + self.chunks[ci].1
138.             &&& self.has_contiguous_free_range(start, count)
139.         }
140.     }
141. 
142.     /// Whether there is a cross-chunk contiguous free range of `count` bits
143.     /// starting in chunk `ci` (the range extends past chunk ci's end).
144.     pub open spec fn has_cross_chunk_free_range_from(&self, ci: int, count: int) -> bool {
145.         &&& 0 <= ci < self.chunks.len()
146.         &&& count > 0
147.         &&& exists|start: int| {
148.             &&& self.chunks[ci].0 <= start
149.             &&& start < self.chunks[ci].0 + self.chunks[ci].1
150.             &&& start + count > self.chunks[ci].0 + self.chunks[ci].1
151.             &&& self.has_contiguous_free_range(start, count)
152.         }
153.     }
154. 
155.     /// Usage: total number of set bits.
156.     pub open spec fn usage(&self) -> int {
157.         self.set_bits.len() as int
158.     }
159. 
160.     /// Whether all bits are set (full).
161.     pub open spec fn is_full(&self) -> bool {
162.         forall|idx: int| #![auto] self.is_covered(idx) ==> self.set_bits.contains(idx)
163.     }
164. 
165.     /// Whether no bits are set (empty).
166.     pub open spec fn is_empty(&self) -> bool {
167.         self.set_bits =~= Set::<int>::empty()
168.     }
169. 
170.     /// Chunk offset accessor.
171.     pub open spec fn chunk_offset(&self, i: int) -> int {
172.         self.chunks[i].0
173.     }
174. 
175.     /// Chunk size accessor.
176.     pub open spec fn chunk_size(&self, i: int) -> int {
177.         self.chunks[i].1
178.     }
179. 
180.     /// Chunk end (exclusive upper bound).
181.     pub open spec fn chunk_end(&self, i: int) -> int {
182.         self.chunks[i].0 + self.chunks[i].1
183.     }
184. }
185. 
186. //==================================================================================================
187. // Chunk Specification Functions
188. //==================================================================================================
189. 
190. impl Chunk {
191.     /// Spec-level offset accessor.
192.     pub closed spec fn spec_offset(&self) -> int {
193.         self.offset as int
194.     }
195. 
196.     /// Spec-level num_bits accessor.
197.     pub closed spec fn spec_num_bits(&self) -> int {
198.         self.bitmap@.num_bits
199.     }
200. 
201.     /// Spec-level end accessor.
202.     pub open spec fn spec_end(&self) -> int {
203.         self.spec_offset() + self.spec_num_bits()
204.     }
205. 
206.     /// Whether the chunk covers `index` at spec level.
207.     pub open spec fn spec_covers(&self, index: int) -> bool {
208.         self.spec_offset() <= index && index < self.spec_end()
209.     }
210. 
211.     /// Chunk-level invariant: the underlying bitmap is valid and range doesn't overflow.
212.     pub closed spec fn inv(&self) -> bool {
213.         &&& self.bitmap.inv()
214.         &&& self.spec_offset() + self.spec_num_bits() <= usize::MAX as int
215.     }
216. }
217. 
218. //==================================================================================================
219. // View Implementation for SparseBitmap
220. //==================================================================================================
221. 
222. /// Lift per-chunk set_bits into the global index space, unioning
223. /// from chunk index `idx` onwards.
224. pub closed spec fn lifted_set_bits(chunks: Seq<Chunk>, idx: int) -> Set<int>
225.     decreases chunks.len() - idx
226. {
227.     if idx >= chunks.len() {
228.         Set::empty()
229.     } else {
230.         let offset = chunks[idx].offset as int;
231.         let bv = chunks[idx].bitmap@;
232.         let shifted = Set::new(|g: int|
233.             bv.set_bits.contains(g - offset)
234.         );
235.         shifted.union(lifted_set_bits(chunks, idx + 1))
236.     }
237. }
238. 
239. impl View for SparseBitmap {
240.     type V = SparseBitmapView;
241. 
242.     closed spec fn view(&self) -> SparseBitmapView {
243.         SparseBitmapView {
244.             chunks: Seq::new(self.chunks@.len(), |i: int| (
245.                 self.chunks@[i].offset as int,
246.                 self.chunks@[i].bitmap@.num_bits,
247.             )),
248.             set_bits: lifted_set_bits(self.chunks@, 0),
249.         }
250.     }
251. }
252. 
253. //==================================================================================================
254. // SparseBitmap Invariant
255. //==================================================================================================
256. 
257. impl SparseBitmap {
258.     /// Public invariant: view is well-formed and concrete state is consistent.
259.     pub open spec fn inv(&self) -> bool {
260.         &&& self@.wf()
261.         &&& self.internal_inv()
262.     }
263. 
264.     /// Internal invariant connecting concrete state to abstract view.
265.     pub closed spec fn internal_inv(&self) -> bool {
266.         // The chunks vector is non-empty
267.         &&& self.chunks@.len() > 0
268. 
269.         // All per-chunk bitmaps satisfy their own invariant
270.         &&& forall|i: int| 0 <= i < self.chunks@.len()
271.             ==> (#[trigger] self.chunks@[i]).bitmap.inv()
272. 
273.         // Per-chunk bitmap sizes are positive (from Bitmap::internal_inv, opaque cross-crate)
274.         &&& forall|i: int| #![auto] 0 <= i < self.chunks@.len()
275.             ==> self.chunks@[i].bitmap@.num_bits > 0
276. 
277.         // Per-chunk set_bits are finite (from Bitmap::internal_inv, opaque cross-crate)
278.         &&& forall|i: int| #![auto] 0 <= i < self.chunks@.len()
279.             ==> self.chunks@[i].bitmap@.set_bits.finite()
280. 
281.         // Chunk ranges do not overflow usize (from constructor validation)
282.         &&& forall|i: int| #![auto] 0 <= i < self.chunks@.len()
283.             ==> self.chunks@[i].offset as int + self.chunks@[i].bitmap@.num_bits
284.                 <= usize::MAX as int
285. 
286.         // Chunks are sorted and non-overlapping (from constructor sort + overlap check)
287.         &&& forall|i: int, j: int| #![auto] 0 <= i < j < self.chunks@.len()
288.             ==> self.chunks@[i].offset as int + self.chunks@[i].bitmap@.num_bits
289.                 <= self.chunks@[j].offset as int
290. 
291.         // Cached capacity matches the sum of chunk sizes
292.         &&& self.capacity_bits as int == self@.capacity()
293. 
294.         // next_chunk_hint is a valid index into the chunks vector
295.         &&& (self.next_chunk_hint as int) < self.chunks@.len()
296. 
297.         // The view's chunks sequence matches the concrete chunks
298.         &&& self@.chunks.len() == self.chunks@.len()
299.         &&& forall|i: int| #![auto] 0 <= i < self.chunks@.len() ==> {
300.             &&& self@.chunks[i].0 == self.chunks@[i].offset as int
301.             &&& self@.chunks[i].1 == self.chunks@[i].bitmap@.num_bits
302.         }
303.     }
304. }
305. 
306. //==================================================================================================
307. // Input Sequence Helpers (for new() specification)
308. //==================================================================================================
309. 
310. /// Total capacity from an input sequence of (offset, Bitmap) pairs.
311. /// Sort-invariant: the sum does not depend on element order.
312. pub open spec fn input_capacity(input: Seq<(usize, Bitmap)>, idx: int) -> int
313.     decreases input.len() - idx
314. {
315.     if idx >= input.len() {
316.         0
317.     } else {
318.         input[idx].1@.num_bits + input_capacity(input, idx + 1)
319.     }
320. }
321. 
322. /// Lifted set_bits from an input sequence of (offset, Bitmap) pairs.
323. /// Each bitmap's set_bits are shifted by its associated offset.
324. /// Sort-invariant: the union does not depend on element order.
325. pub open spec fn input_lifted_set_bits(input: Seq<(usize, Bitmap)>, idx: int) -> Set<int>
326.     decreases input.len() - idx
327. {
328.     if idx >= input.len() {
329.         Set::empty()
330.     } else {
331.         let offset = input[idx].0 as int;
332.         let bv = input[idx].1@;
333.         let shifted = Set::new(|g: int| bv.set_bits.contains(g - offset));
334.         shifted.union(input_lifted_set_bits(input, idx + 1))
335.     }
336. }
337. 
338. /// Total capacity from a sequence of Chunk structs (sum of bitmap sizes).
339. pub closed spec fn chunk_seq_capacity(chunks: Seq<Chunk>, idx: int) -> int
340.     decreases chunks.len() - idx
341. {
342.     if idx >= chunks.len() {
343.         0
344.     } else {
345.         chunks[idx].bitmap@.num_bits + chunk_seq_capacity(chunks, idx + 1)
346.     }
347. }
348. 
349. } // verus!
